import{_ as d,o as r,c as a,a0 as e}from"./chunks/framework.UHt1LHnn.js";const u=JSON.parse('{"title":"CHAPTER 2. 반복 업무의 종말","description":"","frontmatter":{},"headers":[],"relativePath":"ch2.md","filePath":"ch2.md"}'),o={name:"ch2.md"};function h(l,t,n,s,i,c){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="chapter-2-반복-업무의-종말" tabindex="-1">CHAPTER 2. 반복 업무의 종말 <a class="header-anchor" href="#chapter-2-반복-업무의-종말" aria-label="Permalink to &quot;CHAPTER 2. 반복 업무의 종말&quot;">​</a></h1><blockquote><p>매일 낭비하던 시간을 AI가 돌려줬다</p></blockquote><h2 id="🕐-claude-code-도입-전-나의-하루-업무-루틴" tabindex="-1">🕐 Claude Code 도입 전, 나의 하루 업무 루틴 <a class="header-anchor" href="#🕐-claude-code-도입-전-나의-하루-업무-루틴" aria-label="Permalink to &quot;🕐 Claude Code 도입 전, 나의 하루 업무 루틴&quot;">​</a></h2><p>기획자의 하루는 겉으로는 바빠 보이지만, 실제로 얼마나 많은 시간이 **&quot;진짜 기획&quot;**에 쓰이고 있을까요? 도입 전 하루를 솔직하게 되돌아봤습니다.</p><table tabindex="0"><thead><tr><th>시간대</th><th>업무</th><th>실제로 걸린 시간</th></tr></thead><tbody><tr><td>오전 09~10시</td><td>전날 회의록 정리 및 Confluence 업로드</td><td>약 40분</td></tr><tr><td>오전 10~11시</td><td>Jira 티켓 상태 확인 및 코멘트 업데이트</td><td>약 30분</td></tr><tr><td>오후 02~04시</td><td>경쟁사 리서치 자료 수집 및 기획서/보고서 초안</td><td>약 2시간</td></tr><tr><td>오후 04~05시</td><td>API 스펙 변경에 따른 문서 수정 및 공유</td><td>약 1시간</td></tr><tr><td>수시</td><td>Google Chat 문의 대응, 문서 링크 찾기</td><td>약 1시간+</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">😓 하루 8시간 중 진짜 기획에 쓴 시간은?</p><p>위 항목들만 합쳐도 하루 <strong>5시간 이상</strong>이 반복·행정 업무에 소요됩니다.<br> 실제 서비스 방향을 고민하고, 사용자 경험을 설계하는 &quot;진짜 기획&quot;에 쓸 수 있는 시간은 <strong>하루 2~3시간</strong>에 불과했습니다.</p></div><h2 id="🔍-자동화-대상-업무-발굴-방법" tabindex="-1">🔍 자동화 대상 업무 발굴 방법 <a class="header-anchor" href="#🔍-자동화-대상-업무-발굴-방법" aria-label="Permalink to &quot;🔍 자동화 대상 업무 발굴 방법&quot;">​</a></h2><p>Claude Code 도입에 앞서, 어떤 업무부터 자동화할지 기준을 세웠습니다. 아래 3가지 조건을 모두 충족하는 업무를 우선 대상으로 삼았습니다.</p><table tabindex="0"><thead><tr><th>기준</th><th>설명</th><th>자동화 적합도</th></tr></thead><tbody><tr><td><strong>① 반복 빈도가 높다</strong></td><td>매일 또는 매주 동일한 패턴으로 발생하는 업무</td><td>⭐⭐⭐</td></tr><tr><td><strong>② 판단보다 실행이 많다</strong></td><td>창의적 사고보다 정해진 형식에 맞춰 옮기는 작업</td><td>⭐⭐⭐</td></tr><tr><td><strong>③ 실수가 잦다</strong></td><td>복붙·수동 입력 과정에서 오타나 누락이 자주 발생</td><td>⭐⭐</td></tr></tbody></table><h3 id="내-업무-중-자동화-대상으로-선정한-항목" tabindex="-1">내 업무 중 자동화 대상으로 선정한 항목 <a class="header-anchor" href="#내-업무-중-자동화-대상으로-선정한-항목" aria-label="Permalink to &quot;내 업무 중 자동화 대상으로 선정한 항목&quot;">​</a></h3><table tabindex="0"><thead><tr><th>업무</th><th>자동화 방법</th><th>관련 챕터</th></tr></thead><tbody><tr><td>회의록 작성 및 Confluence 업로드</td><td>MCP Confluence 연동으로 초안 생성 및 자동 업로드</td><td>CH.3</td></tr><tr><td>Jira 티켓 생성·상태 업데이트</td><td>MCP Jira 연동으로 명령어 한 줄 처리</td><td>CH.4</td></tr><tr><td>경쟁사·레퍼런스 분석 보고서</td><td>웹 리서치 → 구조화 → 문서 출력 자동화</td><td>CH.8</td></tr><tr><td>API 스펙 검증</td><td>Swagger JSON 기반 자동화 테스트 툴 구축</td><td>CH.7</td></tr><tr><td>사용자 가이드 문서 초안</td><td>KC-docs clone 후 Claude Code로 초안 작성</td><td>CH.6</td></tr></tbody></table><h2 id="📊-도입-전후-업무-시간-비교" tabindex="-1">📊 도입 전후 업무 시간 비교 <a class="header-anchor" href="#📊-도입-전후-업무-시간-비교" aria-label="Permalink to &quot;📊 도입 전후 업무 시간 비교&quot;">​</a></h2><p>Claude Code 도입 후 약 한 달간 주요 업무별 소요 시간을 측정했습니다.</p><table tabindex="0"><thead><tr><th>업무</th><th>도입 전</th><th>도입 후</th><th>단축 효과</th></tr></thead><tbody><tr><td>회의록 정리 및 업로드</td><td>약 40분</td><td>약 10분</td><td><strong>75% ↓</strong></td></tr><tr><td>Jira 티켓 생성·관리</td><td>약 30분</td><td>약 5분</td><td><strong>83% ↓</strong></td></tr><tr><td>경쟁사 기획서/보고서 초안</td><td>약 2시간</td><td>약 30분</td><td><strong>75% ↓</strong></td></tr><tr><td>API 스펙 검증</td><td>약 1시간</td><td>약 10분</td><td><strong>83% ↓</strong></td></tr><tr><td>사용자 가이드 초안</td><td>약 3시간</td><td>약 40분</td><td><strong>78% ↓</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">📈 수치로 본 변화</p><ul><li>반복 업무 소요 시간: 하루 평균 <strong>5시간 → 1.5시간</strong>으로 단축</li><li>확보된 여유 시간: 하루 <strong>약 3~4시간</strong> — 실제 기획·분석에 재투자</li><li>문서 품질: 형식 오류·누락 빈도 <strong>현저히 감소</strong></li><li>심리적 변화: 반복 작업 스트레스 감소, 기획 본연의 업무 집중도 향상</li></ul></div><h2 id="💡-자동화가-어려운-업무도-있다" tabindex="-1">💡 자동화가 어려운 업무도 있다 <a class="header-anchor" href="#💡-자동화가-어려운-업무도-있다" aria-label="Permalink to &quot;💡 자동화가 어려운 업무도 있다&quot;">​</a></h2><p>모든 업무가 자동화 대상은 아닙니다. Claude Code 도입 과정에서 **&quot;이건 AI가 대신할 수 없다&quot;**는 것도 명확해졌습니다.</p><table tabindex="0"><thead><tr><th>자동화 하기 어려운 업무</th><th>이유</th></tr></thead><tbody><tr><td>이해관계자 설득 및 협의</td><td>맥락과 관계 기반의 판단이 필요</td></tr><tr><td>서비스 방향성 결정</td><td>비즈니스 목표와 사용자 니즈의 균형 조율</td></tr><tr><td>신규 기능의 UX 설계</td><td>창의적 발상과 사용자 공감 능력 필요</td></tr><tr><td>팀 내 갈등 조율</td><td>감성적 판단과 상황 대응 능력 필요</td></tr></tbody></table><p>Claude Code는 기획자를 대체하는 도구가 아닙니다. <strong>반복 실행을 대신 맡아주는 동안, 기획자는 더 본질적인 일에 집중할 수 있게 됩니다.</strong> 다음 챕터부터는 각 자동화 사례를 실전 워크플로우로 상세히 다룹니다.</p>',19)])])}const g=d(o,[["render",h]]);export{u as __pageData,g as default};
